export const code = async (inputs) => {
  const companies_raw = inputs.companies_raw || [];
  const party_raw = inputs.party_raw || [];
  const companies = [];
  for (let i = 1; i < companies_raw.length; i++) {
    const row = companies_raw[i];
    if (row && row[0] && row[1]) {
      companies.push({
        companyID: row[0],
        tallyCompanyName: row[1]
      });
    }
  }
  const existingGUIDs = new Map();
  const existingPartyIDs = [];
  for (let i = 1; i < party_raw.length; i++) {
    const row = party_raw[i];
    if (row && row[16]) {
      existingGUIDs.set(row[16], {
        rowNumber: i + 1,
        PartyID: row[0],
        CompanyID: row[1],
        PartyName: row[2],
        PartyType: row[3],
        GroupID: row[4],
        ContactPerson: row[5],
        Phone: row[6],
        Email: row[7],
        Address: row[8],
        GSTIN: row[9],
        OpeningBalance: parseFloat(row[10]) || 0,
        CreditLimit: parseFloat(row[11]) || 0,
        CreditDays: parseInt(row[12]) || 0,
        CreatedAt: row[13],
        UpdatedAt: row[14],
        Version: parseInt(row[15]) || 1,
        TallyGUID: row[16]
      });
    }
    if (row && row[0]) {
      existingPartyIDs.push(row[0]);
    }
  }
  await store.set('accumulatedNew', []);
  await store.set('accumulatedUpd', []);
  await store.set('existingGUIDsMap', Array.from(existingGUIDs.entries()));
  await store.set('existingPartyIDs', existingPartyIDs);
  await store.set('companies', companies);
  await store.set('groupMap', [['Sundry Debtors', 'GRP-0001'], ['Sundry Creditors', 'GRP-0002']]);
  return {
    companiesCount: companies.length,
    existingCount: existingGUIDs.size,
    companies: companies
  };
};

export const code = async (inputs) => {
  const xml = inputs.xml || '';
  const ledgers = [];
  const regex = /<LEDGER[^>]*>([\s\S]*?)<\/LEDGER>/gi;
  let match;
  while ((match = regex.exec(xml)) !== null) {
    const ledgerXml = match[1];
    const getTag = (tag) => {
      const r = new RegExp(`<${tag}[^>]*>([\s\S]*?)<\/${tag}>`, 'i');
      const m = ledgerXml.match(r);
      return m ? m[1].trim() : '';
    };
    const addrLines = [];
    const addrRegex = /<ADDRESS[^>]*>([\s\S]*?)<\/ADDRESS>/gi;
    let addrMatch;
    while ((addrMatch = addrRegex.exec(ledgerXml)) !== null) {
      addrLines.push(addrMatch[1].trim());
    }
    ledgers.push({
      guid: getTag('GUID'),
      name: getTag('NAME'),
      parent: getTag('PARENT'),
      address: addrLines.join(', '),
      email: getTag('EMAIL'),
      mobile: getTag('LEDGERMOBILE') || getTag('PARTYMOBILE'),
      gstin: getTag('LEDGERGSTIN') || getTag('PARTYGSTIN'),
      openingBalance: parseFloat(getTag('OPENINGBALANCE')) || 0,
      creditLimit: parseFloat(getTag('CREDITLIMIT')) || 0,
      creditPeriod: parseInt((getTag('CREDITPERIOD') || '').match(/\d+/) || ['0']) || 0,
      source: 'Debtor'
    });
  }
  return { ledgers, count: ledgers.length };
};

