export const code = async (inputs) => {
  const debtors = inputs.debtors || [];
  const creditors = inputs.creditors || [];
  const companyID = inputs.companyID;
  const existingGUIDsMap = await store.get('existingGUIDsMap') || [];
  const existingGUIDs = new Map(existingGUIDsMap);
  const existingPartyIDs = await store.get('existingPartyIDs') || [];
  const groupMap = new Map(await store.get('groupMap') || []);
  const SIGN_FLIP = await store.get('SIGN_FLIP') === 'true';
  const merged = new Map();
  for (const d of debtors) {
    merged.set(d.guid, { ...d, partyType: 'Customer' });
  }
  for (const c of creditors) {
    if (merged.has(c.guid)) {
      merged.get(c.guid).partyType = 'Both';
    } else {
      merged.set(c.guid, { ...c, partyType: 'Supplier' });
    }
  }
  const newRows = [];
  const updatedRows = [];
  let maxID = existingPartyIDs
    .filter(id => id && id.startsWith('PTY-'))
    .map(id => parseInt(id.replace('PTY-', '')))
    .reduce((a, b) => Math.max(a, b), 0);
  const genID = () => {
    maxID++;
    return 'PTY-' + maxID.toString().padStart(4, '0');
  };
  const now = () => new Date().toISOString().replace('T', ' ').substring(0, 19);
  const deriveType = (parent, existingType) => {
    const p = (parent || '').toLowerCase();
    if (p.includes('debtor')) return 'Customer';
    if (p.includes('creditor')) return 'Supplier';
    if (existingType === 'Both') return 'Both';
    return 'Unclassified';
  };
  for (const [guid, t] of merged) {
    const existing = existingGUIDs.get(guid);
    if (!existing) {
      newRows.push({
        PartyID: genID(),
        CompanyID: companyID,
        PartyName: t.name,
        PartyType: deriveType(t.parent, t.partyType),
        GroupID: groupMap.get(t.parent) || '',
        ContactPerson: '',
        Phone: t.mobile,
        Email: t.email,
        Address: t.address,
        GSTIN: t.gstin,
        OpeningBalance: SIGN_FLIP ? -t.openingBalance : t.openingBalance,
        CreditLimit: t.creditLimit,
        CreditDays: t.creditPeriod,
        CreatedAt: now(),
        UpdatedAt: now(),
        Version: 1,
        TallyGUID: guid
      });
    } else {
      const changes = t.name !== existing.PartyName ||
        deriveType(t.parent, t.partyType) !== existing.PartyType ||
        (groupMap.get(t.parent) || '') !== existing.GroupID ||
        (t.mobile || '') !== (existing.Phone || '') ||
        (t.email || '') !== (existing.Email || '') ||
        t.address !== existing.Address ||
        (t.gstin || '') !== (existing.GSTIN || '') ||
        (SIGN_FLIP ? -t.openingBalance : t.openingBalance) !== existing.OpeningBalance ||
        t.creditLimit !== existing.CreditLimit ||
        t.creditPeriod !== existing.CreditDays;
      if (changes) {
        updatedRows.push({
          ...existing,
          PartyName: t.name,
          PartyType: deriveType(t.parent, t.partyType),
          GroupID: groupMap.get(t.parent) || existing.GroupID,
          Phone: t.mobile || existing.Phone,
          Email: t.email || existing.Email,
          Address: t.address,
          GSTIN: t.gstin || existing.GSTIN,
          OpeningBalance: SIGN_FLIP ? -t.openingBalance : t.openingBalance,
          CreditLimit: t.creditLimit,
          CreditDays: t.creditPeriod,
          UpdatedAt: now(),
          Version: existing.Version + 1
        });
      }
    }
  }
  const currentNew = await store.get('accumulatedNew') || [];
  await store.set('accumulatedNew', [...currentNew, ...newRows]);
  const currentUpd = await store.get('accumulatedUpd') || [];
  await store.set('accumulatedUpd', [...currentUpd, ...updatedRows]);
  return {
    newCount: newRows.length,
    updCount: updatedRows.length,
    companyID
  };
};

export const code = async (inputs) => {
  const newRows = await store.get('accumulatedNew') || [];
  const updRows = await store.get('accumulatedUpd') || [];
  const TEST_MODE = await store.get('TEST_MODE') === 'true';
  const targetSheet = TEST_MODE ? 'PartyStaging' : 'Party';
  const rowsForAppend = newRows.map(r => [
    r.PartyID, r.CompanyID, r.PartyName, r.PartyType, r.GroupID,
    r.ContactPerson, r.Phone, r.Email, r.Address, r.GSTIN,
    r.OpeningBalance, r.CreditLimit, r.CreditDays,
    r.CreatedAt, r.UpdatedAt, r.Version, r.TallyGUID
  ]);
  const updatesForBatch = updRows.map(r => ({
    rowNumber: r.rowNumber,
    values: [
      r.PartyID, r.CompanyID, r.PartyName, r.PartyType, r.GroupID,
      r.ContactPerson, r.Phone, r.Email, r.Address, r.GSTIN,
      r.OpeningBalance, r.CreditLimit, r.CreditDays,
      r.CreatedAt, r.UpdatedAt, r.Version, r.TallyGUID
    ]
  }));
  return {
    testMode: TEST_MODE,
    targetSheet,
    newCount: newRows.length,
    updCount: updRows.length,
    rowsForAppend,
    updatesForBatch
  };
};
